head.script:
scwin.screenId = "jldfil00174";

///////// 1. 변수 및 선언 영역 /////////

scwin.formObj = undefined;

scwin.rtnVal = "";

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.formObj = undefined;


///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "iframe_12", attr: "src", fn: function () { return "/submission/searchDisclosureDocument.do?method=srchDigitalListCorpIsuList&tgtIsurCd=" + String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("tgtIsurCd"))) + "&pageSize=10"; } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.formObj = (document.popForm || { elements: [] });
        const openerOjb = scwin.frame.document.comFrm;
        $c.util.getComponent("ipt_formKey").setValue(openerOjb.formKey.value);
        $c.util.getComponent("ipt_returnKey").setValue(openerOjb.returnKey.value);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00174.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.chkArrNo = undefined; try { scwin.chkArrNo = /* sdd-asis-lifecycle:begin chkArrNo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array(0)/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00174' }); }

scwin.chkTitle = undefined; try { scwin.chkTitle = /* sdd-asis-lifecycle:begin chkTitle — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array(0)/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00174' }); }

scwin.obj = undefined; try { scwin.obj = /* sdd-asis-lifecycle:begin obj — as-is 원문 본문(전환 이관 · 포팅 적용됨) */opener.Potential.Provider/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00174' }); }

scwin.frameId = undefined; try { scwin.frameId = /* sdd-asis-lifecycle:begin frameId — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.obj.ActiveFrame.FrameID/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00174' }); }

scwin.frame = undefined; try { scwin.frame = /* sdd-asis-lifecycle:begin frame — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.obj.Provider(scwin.frameId).ActiveFrame/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00174' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_attrReals();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil00174.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_selectedAll_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_selectedAll_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_selectedAll_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.selectedAll()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00174.btn_selectedAll_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_selected_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_selected_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_selected_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.selected()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00174.btn_selected_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_close_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_close_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_close_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.close()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00174.btn_close_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_selectedAll
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_selectedAll = async function () {
    const sbmOptions = {
        id: "tx_fn_selectedAll",
        method: "post",
        action: "/submission/ajaxGetListData.do?method=ajaxGetDigitalListCorpIsuList",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil00174.tx_fn_selectedAll" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.checkIt
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.checkIt = function (ver) {
    /* sdd-asis-lifecycle:begin checkIt — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const subObj = document.iframe.searchForm.bndIsuInfo;
    let tmpVal = null;
    let arrLength = 0;
    const arrNo = ((ver.value).split("|"))[0];
    scwin.resetRtnVal(arrNo);
    if (scwin.chkArrNo.length != 0) {
        arrLength = scwin.chkArrNo.length;
    }
    if (ver.checked === true) {
        tmpVal = (ver.value).split("|");
        scwin.chkArrNo[arrLength] = tmpVal[0];
        scwin.chkTitle[arrLength] = tmpVal[1];
    }
    scwin.rtnVal = scwin.chkArrNo.join(",") + "|" + scwin.chkArrNo.join("\n");
    (($c.util.getComponent("txt_docs")) && ($c.util.getComponent("txt_docs")).setValue ? ($c.util.getComponent("txt_docs")).setValue(scwin.chkTitle.join(", ")) : (($c.util.getComponent("txt_docs")) ? (($c.util.getComponent("txt_docs")).innerHTML = scwin.chkTitle.join(", ")) : void (scwin.chkTitle.join(", "))));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.resetRtnVal
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.resetRtnVal = function (ver) {
    /* sdd-asis-lifecycle:begin resetRtnVal — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const tmpArr1 = new Array(0);
    const tmpArr2 = new Array(0);
    let cnt = 0;
    for (let i = 0; i < scwin.chkArrNo.length; i++) {
        if (scwin.chkArrNo[i] !== ver) {
            tmpArr1[cnt] = scwin.chkArrNo[i];
            tmpArr2[cnt] = scwin.chkTitle[i];
            cnt++;
        }
    }
    scwin.chkArrNo = new Array(0);
    scwin.chkTitle = new Array(0);
    scwin.chkArrNo = tmpArr1;
    scwin.chkTitle = tmpArr2;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.selected
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.selected = async function () {
    /* sdd-asis-lifecycle:begin fn_selected — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.formObj = (document.popForm || { elements: [] });
    let isChoice = false;
    const subObj = document.iframe.searchForm.bndIsuInfo;
    if (scwin.chkArrNo.length != 0) {
        isChoice = true;
    }
    if (isChoice) {
        scwin.frame.fn_setSelectedData($c.util.getComponent("ipt_formKey").getValue(), $c.util.getComponent("ipt_keyValue").getValue(), decodeURIComponent($c.util.getComponent("ipt_returnKey").getValue()), scwin.chkArrNo.join(","), scwin.chkTitle.join(",\n"));
        $c.win.closePopup();
    } else {
        await $c.win.alert("종목을 하나 이상 선택하세요!");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCheckedCheckBox
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.setCheckedCheckBox = function (ver) {
    /* sdd-asis-lifecycle:begin setCheckedCheckBox — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const subObj = document.iframe.searchForm.bndIsuInfo;
    let tmpVal = null;
    if (ver != 0) {
        if (scwin.chkArrNo.length != 0) {
            for (let i = 0; i < scwin.chkArrNo.length; i++) {
                for (let k = 0; k < subObj.bndIsuInfo.length; k++) {
                    tmpVal = (subObj.bndIsuInfo[k].value).split("|");
                    if (scwin.chkArrNo[i] === tmpVal[0]) {
                        subObj.bndIsuInfo[k].checked = true;
                    }
                }
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.close
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.close = function () {
    /* sdd-asis-lifecycle:begin fn_close — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
/**
 * @method
 * @name scwin.selectedAllDone
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.selectedAllDone = async function (data) {
    /* sdd-asis-lifecycle:begin fn_selectedAll_done — as-is 원문 본문(전환 이관 · 포팅 적용됨) */await $c.win.alert('대상종목으로 ' + data.arrCount + '건이 선택되었습니다.');
    (($c.util.getComponent("txt_docs")) && ($c.util.getComponent("txt_docs")).setValue ? ($c.util.getComponent("txt_docs")).setValue(data.isuCodeNmArr) : (($c.util.getComponent("txt_docs")) ? (($c.util.getComponent("txt_docs")).innerHTML = data.isuCodeNmArr) : void (data.isuCodeNmArr)));
    scwin.frame.fn_setSelectedData($c.util.getComponent("ipt_formKey").getValue(), $c.util.getComponent("ipt_keyValue").getValue(), decodeURIComponent($c.util.getComponent("ipt_returnKey").getValue()), data.isuCodeArr, data.isuCodeNmArr);
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.selectedAll
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.selectedAll = async function () {
    const r = await scwin.tx_fn_selectedAll();
    try {
        scwin.selectedAllDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil00174.fn_selectedAll' });
    }
    return r;
};
